/* UXTeam Design System JS. Generated by scripts/build.mjs */

/* ===== js/core.js ===== */
/**
 * UXTeam DS core. Every component registers an init function here.
 * Components look for their own data attribute and do nothing when it is
 * missing, so the same bundle can load on every page.
 */
(function () {
  'use strict';
  var registry = [];
  window.UXTeam = {
    register: function (name, init) {
      registry.push({ name: name, init: init });
    },
    init: function (root) {
      root = root || document;
      registry.forEach(function (c) {
        try {
          c.init(root);
        } catch (e) {
          console.error('[UXTeam] ' + c.name + ' failed to start', e);
        }
      });
    },
    reducedMotion: function () {
      return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    }
  };
  document.addEventListener('DOMContentLoaded', function () {
    window.UXTeam.init(document);
  });
})();


/* ===== sections/site-header/site-header.js ===== */
/**
 * Site header: mobile menu toggle.
 * Desktop dropdowns are not designed yet; the caret buttons only flip
 * aria-expanded so a future menu can hook in.
 */
UXTeam.register('site-header', function (root) {
  root.querySelectorAll('[data-ux-header]').forEach(function (header) {
    if (header.dataset.uxReady) return;
    header.dataset.uxReady = '1';
    var toggle = header.querySelector('.ux-header__toggle');
    var panel = header.querySelector('.ux-mobile-nav');
    if (toggle && panel) {
      toggle.addEventListener('click', function () {
        var open = toggle.getAttribute('aria-expanded') !== 'true';
        toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
        toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
        panel.hidden = !open;
        header.classList.toggle('is-menu-open', open);
      });
    }
    header.querySelectorAll('.ux-nav__link--menu').forEach(function (btn) {
      btn.addEventListener('click', function () {
        btn.setAttribute('aria-expanded', btn.getAttribute('aria-expanded') === 'true' ? 'false' : 'true');
      });
    });
  });
});


/* ===== components/faq/faq.js ===== */
/**
 * FAQ accordion. Markup: [data-ux-faq] > .ux-faq__item > button.ux-faq__question + .ux-faq__panel
 * One item open per list. Panel height animates (420ms, set in CSS).
 */
UXTeam.register('faq', function (root) {
  root.querySelectorAll('[data-ux-faq]').forEach(function (list) {
    if (list.dataset.uxReady) return;
    list.dataset.uxReady = '1';
    var items = Array.prototype.slice.call(list.querySelectorAll('.ux-faq__item'));

    function setOpen(item, open) {
      var btn = item.querySelector('.ux-faq__question');
      var panel = item.querySelector('.ux-faq__panel');
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
      if (open) {
        item.classList.add('is-open');
        panel.style.height = panel.scrollHeight + 'px';
      } else {
        panel.style.height = panel.scrollHeight + 'px';
        panel.offsetHeight; // force layout so the close animates
        item.classList.remove('is-open');
        panel.style.height = '0px';
      }
    }

    items.forEach(function (item, i) {
      var btn = item.querySelector('.ux-faq__question');
      var panel = item.querySelector('.ux-faq__panel');
      var id = panel.id || 'ux-faq-' + Math.random().toString(36).slice(2, 8) + '-' + i;
      panel.id = id;
      btn.setAttribute('aria-controls', id);
      var startOpen = item.classList.contains('is-open');
      btn.setAttribute('aria-expanded', startOpen ? 'true' : 'false');
      panel.style.height = startOpen ? 'auto' : '0px';

      panel.addEventListener('transitionend', function (e) {
        if (e.propertyName === 'height' && item.classList.contains('is-open')) {
          panel.style.height = 'auto';
        }
      });

      btn.addEventListener('click', function () {
        var willOpen = !item.classList.contains('is-open');
        items.forEach(function (other) {
          if (other !== item && other.classList.contains('is-open')) setOpen(other, false);
        });
        setOpen(item, willOpen);
      });
    });
  });
});


/* ===== components/industry-card/industry-card.js ===== */
/**
 * Industry cards. Markup: [data-ux-industries] > .ux-industry (one has .is-open)
 * Hover or focus a tile to open it. Desktop only (tablet/mobile show all).
 */
UXTeam.register('industry-cards', function (root) {
  root.querySelectorAll('[data-ux-industries]').forEach(function (row) {
    if (row.dataset.uxReady) return;
    row.dataset.uxReady = '1';
    var tiles = Array.prototype.slice.call(row.querySelectorAll('.ux-industry'));
    function open(tile) {
      tiles.forEach(function (t) {
        t.classList.toggle('is-open', t === tile);
      });
    }
    tiles.forEach(function (tile) {
      tile.addEventListener('mouseenter', function () { open(tile); });
      tile.addEventListener('focusin', function () { open(tile); });
    });
  });
});


/* ===== components/toc/toc.js ===== */
/**
 * Table of contents scroll spy + floating section menu (tablet, mobile).
 * Markup: nav.ux-toc[data-ux-toc] with links to #section ids, and an optional
 * .ux-section-menu[data-ux-section-menu] that mirrors the same links.
 */
UXTeam.register('toc', function (root) {
  root.querySelectorAll('[data-ux-toc]').forEach(function (toc) {
    if (toc.dataset.uxReady) return;
    toc.dataset.uxReady = '1';
    var links = Array.prototype.slice.call(toc.querySelectorAll('a[href^="#"]'));
    var sections = links.map(function (a) { return document.querySelector(a.getAttribute('href')); }).filter(Boolean);
    var menu = document.querySelector('[data-ux-section-menu]');
    var menuLabel = menu && menu.querySelector('.ux-section-menu__label');
    var menuLinks = menu ? Array.prototype.slice.call(menu.querySelectorAll('a[href^="#"]')) : [];
    var scope = toc.closest('[data-ux-toc-scope]') || toc.parentElement;

    function setActive(id) {
      links.forEach(function (a) {
        var on = a.getAttribute('href') === '#' + id;
        a.classList.toggle('is-active', on);
        a.parentElement.classList.toggle('is-active', on);
        if (on) a.setAttribute('aria-current', 'true'); else a.removeAttribute('aria-current');
      });
      menuLinks.forEach(function (a) {
        var on = a.getAttribute('href') === '#' + id;
        a.classList.toggle('is-active', on);
        if (on && menuLabel) menuLabel.textContent = a.textContent;
      });
    }

    function onScroll() {
      var line = window.innerHeight * 0.3;
      var current = sections[0];
      sections.forEach(function (s) {
        if (s.getBoundingClientRect().top - line <= 0) current = s;
      });
      if (current) setActive(current.id);
      if (menu) {
        var r = scope.getBoundingClientRect();
        menu.classList.toggle('is-visible', r.top < window.innerHeight * 0.6 && r.bottom > window.innerHeight * 0.4);
      }
    }

    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    onScroll();

    if (menu) {
      var toggle = menu.querySelector('.ux-section-menu__toggle');
      toggle.addEventListener('click', function () {
        var open = !menu.classList.contains('is-open');
        menu.classList.toggle('is-open', open);
        toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
      });
      menuLinks.forEach(function (a) {
        a.addEventListener('click', function () {
          menu.classList.remove('is-open');
          toggle.setAttribute('aria-expanded', 'false');
        });
      });
      document.addEventListener('click', function (e) {
        if (!menu.contains(e.target)) {
          menu.classList.remove('is-open');
          toggle.setAttribute('aria-expanded', 'false');
        }
      });
    }
  });
});


/* ===== components/video-card/video-card.js ===== */
/**
 * Video card. The play button swaps the still for a <video> (or an iframe
 * embed) when data-video is set on [data-ux-video]. Without a source the
 * button does nothing, so the card can ship before the video is ready.
 *   data-video="assets/video/brent-weaver.mp4"            (self hosted)
 *   data-embed="https://player.vimeo.com/video/ID?autoplay=1"  (Vimeo/YouTube)
 */
UXTeam.register('video-card', function (root) {
  root.querySelectorAll('[data-ux-video]').forEach(function (media) {
    if (media.dataset.uxReady) return;
    media.dataset.uxReady = '1';
    var btn = media.querySelector('.ux-play');
    if (!btn) return;
    btn.addEventListener('click', function () {
      var src = media.dataset.video;
      var embed = media.dataset.embed;
      if (!src && !embed) return;
      var el;
      if (embed) {
        el = document.createElement('iframe');
        el.src = embed;
        el.allow = 'autoplay; fullscreen; picture-in-picture';
        el.setAttribute('allowfullscreen', '');
        el.title = btn.getAttribute('aria-label') || 'Video';
      } else {
        el = document.createElement('video');
        el.src = src;
        el.controls = true;
        el.autoplay = true;
        el.playsInline = true;
      }
      el.className = 'ux-video-card__video';
      media.appendChild(el);
      btn.hidden = true;
    });
  });
});


/* ===== sections/logo-marquee/logo-marquee.js ===== */
/**
 * Logo marquee. Duplicates the logo list once so the CSS loop is seamless.
 * Markup: .ux-marquee[data-ux-marquee] > .ux-marquee__track > ul.ux-marquee__group
 */
UXTeam.register('logo-marquee', function (root) {
  root.querySelectorAll('[data-ux-marquee]').forEach(function (m) {
    if (m.dataset.uxReady) return;
    m.dataset.uxReady = '1';
    var track = m.querySelector('.ux-marquee__track');
    var group = track && track.querySelector('.ux-marquee__group');
    if (!group) return;
    var clone = group.cloneNode(true);
    clone.setAttribute('aria-hidden', 'true');
    clone.querySelectorAll('img').forEach(function (img) { img.alt = ''; });
    track.appendChild(clone);
  });
});


/* ===== sections/filter-bar/filter-bar.js ===== */
/**
 * Filter chips. Markup:
 *   <div data-ux-filter="#grid-id"> <button class="ux-chip" data-filter="all|Category"> ...
 *   items in the grid carry data-category="Category"
 * Clicking a chip shows matching items. Static pages only; in WordPress
 * replace with taxonomy links.
 */
UXTeam.register('filter-bar', function (root) {
  root.querySelectorAll('[data-ux-filter]').forEach(function (bar) {
    if (bar.dataset.uxReady) return;
    bar.dataset.uxReady = '1';
    var grid = document.querySelector(bar.dataset.uxFilter);
    if (!grid) return;
    var chips = Array.prototype.slice.call(bar.querySelectorAll('[data-filter]'));
    var empty = grid.parentElement.querySelector('.ux-filter-empty');
    chips.forEach(function (chip) {
      chip.addEventListener('click', function () {
        var f = chip.dataset.filter;
        chips.forEach(function (c) {
          var on = c === chip;
          c.classList.toggle('is-active', on);
          c.setAttribute('aria-pressed', on ? 'true' : 'false');
        });
        var shown = 0;
        grid.querySelectorAll('[data-category]').forEach(function (item) {
          var match = f === 'all' || item.dataset.category === f;
          item.hidden = !match;
          if (match) shown++;
        });
        if (empty) empty.hidden = shown > 0;
      });
    });
  });
});


/* ===== sections/booking-cta/booking-cta.js ===== */
/**
 * Booking form. Checks the work email, then sends the visitor to the
 * Calendly booking page set in data-calendly (name and email prefilled).
 * Until data-calendly is set it only shows a confirmation message.
 */
UXTeam.register('booking-form', function (root) {
  root.querySelectorAll('[data-ux-booking]').forEach(function (form) {
    if (form.dataset.uxReady) return;
    form.dataset.uxReady = '1';
    var status = form.querySelector('.ux-form__status');
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      var email = form.querySelector('[name="email"]');
      var field = email.closest('.ux-field');
      var ok = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value.trim());
      field.classList.toggle('is-invalid', !ok);
      email.setAttribute('aria-invalid', ok ? 'false' : 'true');
      if (!ok) { email.focus(); return; }
      var url = form.dataset.calendly;
      if (url) {
        var name = form.querySelector('[name="name"]').value.trim();
        var q = new URLSearchParams({ name: name, email: email.value.trim() });
        window.location.href = url + (url.indexOf('?') > -1 ? '&' : '?') + q.toString();
      } else if (status) {
        status.textContent = 'Thanks. Taking you to the booking calendar…';
      }
    });
  });
});
